*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/pre_newlisting.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/jquery-1.11.0.min.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/elastic_search.js");
scwin.vScrenID = "ULDSTF24703.xml";
scwin.clickBzProcsNo = "";
scwin.clickListProcsStatCd = "";
scwin.clickListSchdlDd = "";
scwin.clickListTpClss = "";
scwin.clickIsurCd = "";
scwin.clickComNm = "";
scwin.clickBillSubmitDd = "";
scwin.clickListComiteDelibCaseSeq = "";
scwin.clickSpotIsuTrdMktTpCd = "";
scwin.clickListSchdlDd = "";
scwin.contnId = "";
scwin.startTime = "";
scwin.endTime = "";
scwin.timeMsg = '';
scwin.listType = "";
scwin.params = "";
scwin.pCnt = 1;
scwin.HashMap = function() {
    this.map = new Array();
};
scwin.HashMap.prototype = {
    set: function(key, value) {
        this.map[key] = value.getValue();
    },
    get: function(key) {
        return this.map[key];
    },
    clear: function() {
        this.map = new Array();
    }
};
scwin.h_Data = new HashMap();
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_GetPar = function(arrPar) {
    arrPar[0] = $c.stf.getObjectValue(txb_ISUR_CD);
    arrPar[1] = $c.stf.getObjectValue(txb_COM_NM);
    arrPar[2] = 'A1';
    arrPar[3] = '2';
    arrPar[4] = SEARCH_TYP_APF;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetPar = function(arrPar) {
    txb_ISUR_CD.setValue(arrPar[0].ISUR_CD);
    txb_COM_NM.setValue(arrPar[0].COM_NM);
};
scwin.fn_GetParDtl = function(arrPar) {
    arrPar[0] = scwin.clickIsurCd;
    arrPar[1] = scwin.clickBzProcsNo;
    arrPar[2] = scwin.clickComNm;
    arrPar[3] = scwin.clickBillSubmitDd;
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_init = function() {
    if (js_dep_cd != 'ZSYS') {
        $c.stf.showObj(panel_verify, false);
    } else {
        $c.cm.setColumnProp(grd_List, 'BZPROCSNO', 'Show', 'true');
        $c.cm.setColumnProp(grd_List, 'CONTNID', 'Show', 'true');
        $c.cm.setColumnProp(grd_List, 'LISTCOMITEDELIBCASESEQ', 'Show', 'true');
        $c.cm.setColumnProp(grd_List, 'COMITECASENO', 'Show', 'true');
    }
    $c.stf.setObjectValue(edt_SDate, "20180101");
    $c.stf.setObjectValue(edt_EDate, $c.ut.cGetToday("yyyymmdd"));
    $c.stf.Combo_CBDataSetPeriod(cmb_PeriodTp);
    chb_Grp_All.setValue(1);
    var strSRH_MENU = "상장예비심사신청현황(STF07100)^stf07100,";
    strSRH_MENU += "공모예정사항 및 재무사항(STF07170)^stf07170,";
    strSRH_MENU += "의무보유주식의 처분(STF07070)^stf07070,";
    strSRH_MENU += "신규상장심사(STF07180)^stf07180,";
    strSRH_MENU += "상장예비심사결과 상세조회(STF60002)^stf60002,";
    strSRH_MENU += "상장위원회 조회(STF60003)^stf60003,";
    strSRH_MENU += "심사관련 주요 이슈사항(STF60011)^stf60011";
    cmb_SRH_MENU.CBData = strSRH_MENU;
    cmb_SRH_MENU.setSelectedIndex(0);
    //setObjectValue(txb_SRH_FROM_TO_ITM,  "접수일");

    var strORD_ITM = " ^ ,회사명^comNm,파일명^attachFileNm,등록일^searchDate";
    cmb_ORD_ITM.CBData = strORD_ITM;
    cmb_ORD_ITM.setSelectedIndex(0);
    var strORD_METH = " ^ ,오름차순^asc,내림차순^desc";
    cmb_ORD_METH.CBData = strORD_METH;
    cmb_ORD_METH.setSelectedIndex(0);
    scwin.fn_list_keyword();
};
scwin.fn_list_keyword = function() {
    var url = "/listingCommon.do?method=listGeneral&outputMessageId=LIST_SEARCH_ATTACH_FILE_KEYWORD" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstsrch.recentkeyword.attachfile.select.condition" + "&{P}param01=" + js_emp_no;
    dts_kwd.DataID = encodeURI(url);
    dts_kwd.Reset();
};
scwin.fn_CheckForm = function() {
    if (!$c.stf.checkEmptyValue(edt_SDate, "검색기간 시작일")) return false;
    if (!$c.stf.checkEmptyValue(edt_SDate, "검색기간 종료일")) return false;
    if (!$c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        return false;
    }
    if ($c.ut.trim($c.stf.getObjectValue(txb_FileContent)).length == 1) {
        $c.win.alert("검색어는 두자이상 입력이 필요합니다.");
        return false;
    }
    if ($c.ut.trim($c.stf.getObjectValue(txb_FileName)).length == 1) {
        $c.win.alert("파일명는 두자이상 입력이 필요합니다.");
        return false;
    }
    return true;
};
scwin.fn_allCheck = function() {
    var checkArray = [chb_Grp_HWP, chb_Grp_DOC, chb_Grp_PDF];
    if (chb_Grp_All.checked == true) {
        for (var i = 0; i < checkArray.length; i++) {
            checkArray[i].setValue(0);
        }
    }
};
scwin.fn_search = function() {
    if (scwin.fn_CheckForm()) {
        scwin.listType = '1';
        scwin.fn_list_sync();
    }
};
scwin.fn_list_sync = function() {
    scwin.startTime = new Date().getTime();
    var url = "/ListedSearch.do?method=findElasitcSearch";
    url += "&ElasticSearchURL=" + "/api/elastic/search";
    url += scwin.fn_get_list_prarams();
    url += "&screenId=" + cmb_SRH_MENU.BindColVal;
    url += "&attachBinfileContent=" + $c.stf.getObjectValue(txb_FileContent);
    url += "&EMP_NO=" + js_emp_no;
    url += "&PN=companyCode^screenId^startSearchDate^endSearchDate^attachBinfileContent^attachFileNm^fileType^sortingCriteria^sortingMethod";
    if ($c.stf.getObjectValue(chk_Exclusion) == 'Y') {
        dts_filter.DataID = encodeURI(url);
        dts_filter.Reset();
    } else {
        dts_List.DataID = encodeURI(url);
        dts_List.Reset();
    }
    $c.cm.ShowWin(grd_List);
    grd_List.Redraw = false;
};
scwin.fn_list_sync_rdb = function() {
    scwin.startTime = new Date().getTime();
    var url = "/listingCommon.do?method=listGeneralForDynamicName";
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&outputMessageId=LIST_SEARCH_ATTACH_FILE_RDB";
    url += scwin.fn_get_list_queryId();
    url += scwin.fn_get_list_prarams_rdb();
    if ($c.stf.getObjectValue(chk_Exclusion) == 'Y') {
        dts_filter.DataID = encodeURI(url);
        dts_filter.Reset();
    } else {
        dts_List.DataID = encodeURI(url);
        dts_List.Reset();
    }
    $c.cm.ShowWin(grd_List);
    grd_List.Redraw = false;
};
scwin.fn_get_list_queryId = function() {
    var queryId = "&queryId=";
    if (cmb_SRH_MENU.getSelectedIndex() == 0) queryId += "lds.stf.lstsrch.listInvstgApfm.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() == 1) queryId += "lds.stf.lstsrch.pubfnc.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() == 2) queryId += "lds.stf.lstsrch.prtdepowithd.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() == 3) queryId += "lds.stf.lstsrch.newlist.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() == 4) queryId += "lds.stf.lstsrch.listInvstgApfm_detail.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() == 5) queryId += "lds.stf.lstsrch.comite_case.attachfile.select.condition";

    else if (cmb_SRH_MENU.getSelectedIndex() == 6) queryId += "lds.stf.lstsrch.comitedelib.attachfile.select.condition";
    return queryId;
};
scwin.fn_get_list_prarams = function() {
    var fileExt = '';
    if ($c.stf.getObjectValue(chk_IN_RST_YN) == 'Y') {
        if (scwin.params.indexOf("&P1") == -1) {
            scwin.params = "&P1=^" + cmb_SRH_MENU.BindColVal + "^19000101^19000101^^^^^";
        }
        scwin.pCnt = scwin.pCnt + 1;
    } else {
        scwin.params = "";
        scwin.pCnt = 1;
    }
    scwin.params += "&P" + scwin.pCnt + "=" + $c.stf.getObjectValue(txb_ISUR_CD);
    scwin.params += "^" + cmb_SRH_MENU.BindColVal;
    scwin.params += "^" + $c.stf.getObjectValue(edt_SDate);
    scwin.params += "^" + $c.stf.getObjectValue(edt_EDate);
    scwin.params += "^" + $c.stf.getObjectValue(txb_FileContent);
    scwin.params += "^" + $c.stf.getObjectValue(txb_FileName);
    if ($c.stf.getObjectValue(chb_Grp_HWP) == 'Y') fileExt += 'hwp,hwpx,';
    if ($c.stf.getObjectValue(chb_Grp_DOC) == 'Y') fileExt += 'doc,docx,';
    if ($c.stf.getObjectValue(chb_Grp_PDF) == 'Y') fileExt += 'pdf,';
    if ($c.stf.getObjectValue(chb_Grp_All) == 'Y') fileExt = '';
    fileExt = fileExt.replace(/,$/, '');
    scwin.params += "^" + fileExt;
    var vSortingCriteria = '';
    if (cmb_ORD_ITM.getSelectedIndex() > 0) vSortingCriteria = cmb_ORD_ITM.BindColVal;
    scwin.params += "^" + vSortingCriteria;
    var vSortingMethod = '';
    if (cmb_ORD_METH.getSelectedIndex() > 0) vSortingMethod = cmb_ORD_METH.BindColVal;
    scwin.params += "^" + vSortingMethod;
    return scwin.params;
};
scwin.fn_get_list_prarams_rdb = function() {
    var params = "";
    var fileExt = '';
    if ($c.stf.getObjectValue(chb_Grp_HWP) == 'Y') fileExt += 'hwp,hwpx,';
    if ($c.stf.getObjectValue(chb_Grp_DOC) == 'Y') fileExt += 'doc,docx,';
    if ($c.stf.getObjectValue(chb_Grp_PDF) == 'Y') fileExt += 'pdf,';
    if ($c.stf.getObjectValue(chb_Grp_All) == 'Y') fileExt = '';
    fileExt = fileExt.replace(/,$/, '');
    scwin.params += "&SCREN_ID=" + scwin.vScrenID;
    scwin.params += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    scwin.params += "&inputMessageId=LIST_SEARCH_ATTACH_FILE_RDB";
    scwin.params += "&{P}EMP_NO=" + js_emp_no;
    scwin.params += "&{P}ISUR_CD=" + $c.stf.getObjectValue(txb_ISUR_CD);
    scwin.params += "&{P}SPOT_ISU_TRD_MKT_TP_CD=2";
    scwin.params += "&{P}SRH_FROM=" + $c.stf.getObjectValue(edt_SDate);
    scwin.params += "&{P}SRH_TO=" + $c.stf.getObjectValue(edt_EDate);
    scwin.params += "&{P}FILE_NAME=" + $c.stf.getObjectValue(txb_FileName);
    scwin.params += "&{P}FILE_EXT=" + fileExt;
    scwin.params += "&{P}FILE_SIZE_FROM=";
    scwin.params += "&{P}FILE_SIZE_TO=";
    scwin.params += "&{P}ORD_ITEM=";
    scwin.params += "&{P}ORDER_BY=";
    return scwin.params;
};
scwin.fn_list_filter = function() {
    scwin.h_Data.clear();
    for (var i = 1; i <= dts_filter.getTotalRow(); i++) {
        scwin.h_Data.set(scwin.fn_get_mapkey(dts_filter, i), 'Y');
    }
    if ($c.stf.getObjectValue(chk_Exclusion) == "Y") scwin.fn_list_exclusion();

    else {
        scwin.fn_list_inclusion();
    }
};
scwin.fn_get_mapkey = function(obj, idx) {
    var mapKey = "";
    mapKey = obj.getCellData(idx, "BZPROCSNO") + obj.getCellData(idx, "LISTCOMITEDELIBCASESEQ") + obj.getCellData(idx, "COMITECASENO") + obj.getCellData(idx, "CONTNID") + obj.getCellData(idx, "ATTACHFILENM");
    return mapKey;
};
scwin.fn_list_inclusion = function() {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (scwin.h_Data.get(scwin.fn_get_mapkey(dts_List, i)) != 'Y') {
            $c.cp.removeRow(dts_List, i);
            i--;
        }
    }
};
scwin.fn_list_exclusion = function() {
    for (var i = 1; i <= dts_List.getTotalRow(); i++) {
        if (scwin.h_Data.get(scwin.fn_get_mapkey(dts_List, i)) == 'Y') {
            $c.cp.removeRow(dts_List, i);
            i--;
        }
    }
};
scwin.fn_list_completed = function() {
    grd_List.Redraw = true;
    scwin.footnote(panel_page, dts_List.getTotalRow(), dts_List.getCellData(dts_List.getTotalRow(), "TOTALCOUNT"));
    $c.cm.CloseWin(dts_List.getTotalRow(), grd_List);
    var endTime = new Date().getTime();
    var pt = scwin.endTime - scwin.startTime;
    $c.stf.setObjectValue(edt_performance, "" + (pt / 1000) % 60 + "s");
};
scwin.footnote = function(panelID, localCnt, allCnt) {
    var vText = "<span style='font-size__9pt; font-family:굴림; color:#212863;'>총건수: </span><span style='font-size__9pt; font-family:굴림; color:#5C8BE0; font-weight:bold'>" + $c.stf.FormatNumberEx(localCnt);
    if (allCnt > 200) {
        vText += " (총 " + $c.stf.FormatNumberEx(allCnt) + "개)";
    }
    vText += "</span>";
    panelID.innerHTML = "<table border='0' cellpadding='0' cellspacing='0' height='22' width='100%'>" + "    <tr>" + "        <td align='left' width='2%' nowrap>" + vText + "</td>" + "        <td align='center'></td>" + "        <td align='right' width='30'></td>" + "        <td align='right' width='2%' nowrap>&nbsp;</td>" + "    </tr>" + "</table>";
};
scwin.fn_ExcelDown = function() {
    if (dts_List.getTotalRow() > 0) {
        $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_List, "상장자료상세검색", "", "3");
    } else {
        $c.win.alert("해당데이터가 없습니다. 조회후 다운받으십시요.");
    }
};
scwin.fn_getContnId = function() {
    return scwin.contnId;
};
scwin.fn_invstgApfm1 = async function(row) {
    //0

    //clickBzProcsNo
    //clickSpotIsuTrdMktTpCd
    //clickListTpClss

    var url = "/lstinvstg/ListPrelmInvstg.do?method=loadDetailView&nowPage=20";
    url += "&bzProcsNo=" + scwin.clickBzProcsNo;
    url += "&ldMktTpCd=" + scwin.clickSpotIsuTrdMktTpCd;
    url += "&listTpClssCd=" + scwin.clickListTpClss;
    await $c.frame.CreateDialogFrame("JLDSTF07110.jsp", url, "예비심사 청구계획 처리", 150, 0, 1000, 900, "window");

};
scwin.fn_pubFnc = async function(row) {
    //1

    //clickListProcsStatCd
    var frameId = "frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("ULDSTF07171.gfm", "/lstinvstg/ULDSTF07171.gfm?" + frameId, "공모예정및재무사항 처리", 50, 50, 1000, 800, "window");
};
scwin.fn_prtdepoWithd = async function(row) {
    //2

    //clickBzProcsNo
    var frameId = "&frameID=" + frame.FrameID;
    var url = "/lstinvstg/ULDSTF07071.gfm?BZ_PROCS_NO=" + scwin.clickBzProcsNo + frameId;
    await $c.frame.CreateDialogFrame("DLG_PDW", url, "의무보유주식의 처분 관리", 100, 100, 710, 450, "window");
};
scwin.fn_invstgApfm2 = async function(row) {
    //3

    //clickListProcsStatCd
    //clickListSchdlDd
    //clickListTpClss
    var frameId = "?frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("ULDSTF07181.gfm", "/lstinvstg/ULDSTF07181.gfm" + frameId, "신규상장심사 처리", 100, 50, 1000, 800, "window");
};
scwin.fn_comiteDelib = async function(row) {
    //4

    fn_GetPar = fn_GetParDtl;
    fn_SetPar = undefined;
    //clickListProcsStatCd 
    //clickListSchdlDd 
    //clickIsurCd
    //clickComNm 

    var wth = 600;
    var hgt = 720;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    var frameId = "?frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("DLG_PRECOM_DTL", "/lstinvstg/ULDSTF07106.gfm" + frameId, "예비심사결과", pt.x, pt.y, wth, hgt, "window");
};
scwin.fn_comiteCase = async function(row) {
    //5

    //clickListComiteDelibCaseSeq 
    var frameId = "?frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("LIST_COMITE", "/lstmgt/ULDSTF60004.gfm" + frameId, "상장위원회정보관리", 200, 0, 900, 600, "window");
};
scwin.fn_invstgIsue = async function(row) {
    // 6

    //contnId 

    var wth = 790;
    var hgt = 470;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    var frameId = "?frameID=" + frame.FrameID;
    await $c.frame.CreateDialogFrame("gform", "/lstmgt/ULDSTF60012.gfm" + frameId, "심사관련 이슈사항 수정", pt.x, pt.y, wth, hgt, "window");
};
scwin.fn_OpenDetail = function(row) {
    scwin.contnId = dts_List.getCellData(row, "CONTNID");
    scwin.clickBzProcsNo = dts_List.getCellData(row, "BZPROCSNO");
    scwin.clickListProcsStatCd = dts_List.getCellData(row, "LISTPROCSSTATCD");
    //clickListProcsStatCd = '33';

    scwin.clickListSchdlDd = dts_List.getCellData(row, "LISTSCHDLDD");
    scwin.clickListTpClss = dts_List.getCellData(row, "LISTTPCLSSCD");
    scwin.clickIsurCd = dts_List.getCellData(row, "COMPANYCODE");
    scwin.clickBillSubmitDd = dts_List.getCellData(row, "SEARCHDATE"); // BILLSUBMITDD
    scwin.clickComNm = dts_List.getCellData(row, "COMNM");
    scwin.clickListProcsStatCd = dts_List.getCellData(row, "LISTTPCLSSCD");
    scwin.clickSpotIsuTrdMktTpCd = dts_List.getCellData(row, "SPOTISUTRDMKTTPCD");
    scwin.clickListComiteDelibCaseSeq = dts_List.getCellData(row, "LISTCOMITEDELIBCASESEQ");
    switch (cmb_SRH_MENU.getSelectedIndex()) {
        case 0:
            if (dts_List.getCellData(row, "MENUPATH").indexOf("예비심사결과 > 위원회안건") > 0) scwin.fn_comiteDelib(row);

            else scwin.fn_invstgApfm1(row);
            break;
        case 1:
            scwin.fn_pubFnc(row);
            break;
        case 2:
            scwin.fn_prtdepoWithd(row);
            break;
        case 3:
            scwin.fn_invstgApfm2(row);
            break;
        case 4:
            scwin.fn_comiteDelib(row);
            break;
        case 5:
            scwin.fn_comiteCase(row);
            break;
        case 6:
            scwin.fn_invstgIsue(row);
            break;
    }
};
scwin.getRowText = function(rowNum, startCol, endCol, grdObj) {
    var strMatrix = "";
    for (i = startCol; i <= endCol; i++) {
        strMatrix += grdObj.VirtualString2(rowNum, grdObj.GetColumnID(i), 1);
        if (i != endCol) strMatrix += "\t";
    }
    strMatrix += "\r\n";
    return strMatrix;
};
scwin.fn_clearMsg = function() {
    $c.stf.setObjectValue(txb_Msg, "");
    clearInterval(scwin.timeMsg);
};
scwin.grd_List_OnDblClick = function(row, colid) {
