scwin.grd_List_OnCopy = function(lStarRow, bstrStartColId, lEndRow, bstrEndColId) {
    var strMatrix = "";
    var statCol = grd_List.getColumnIndex(bstrStartColId);
    var endCol = grd_List.getColumnIndex(bstrEndColId);
    for (var i = lStarRow; i <= lEndRow; i++) {
        if (dts_List.RowMark(i) == 1) {
            strMatrix += scwin.getRowText(i, statCol, endCol, grd_List); //CopyToClipboard(StartRow,startColid,EndRow,EndColid,grdObj)

        }
    }
    if (strMatrix != "") {
        window.clipboardData.setData("Text", strMatrix);
        $c.stf.setObjectValue(txb_Msg, "클립보드에 복사되었습니다.");
        scwin.timeMsg = setTimeout("fn_clearMsg()", 3000);
    }
};
